-- Marchands de Razor Hill : leurs pièces d'équipement d'origine (gardées dans solazeroth_v3_marchands_origine)
-- sont remplacées par nos pièces fabriquées.
CREATE TABLE IF NOT EXISTS solazeroth_v3_marchands_origine SELECT v.* FROM npc_vendor v JOIN item_template i ON i.entry = v.item WHERE v.entry IN (3163,3166,3167) AND i.class IN (2, 4);
